WITH kept AS (SELECT s.* FROM orders s WHERE NOT EXISTS (SELECT 1 FROM shipments ch WHERE ch.order_id = s.id AND ch.carrier IN ('Kerry', 'DHL'))) SELECT s.id, s.customer_id, s.store_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.shipping_fee, (SELECT SUM(t2.revenue) FROM store_sales t2 WHERE t2.store_id = s.store_id) AS sum_store_sale_revenue FROM kept s ORDER BY sum_store_sale_revenue DESC NULLS LAST, store_id;
